package com.hbm.client.oilextraction;
import com.hbm.client.model.LegacyItemTransforms;import com.hbm.machine.oilextraction.*;import com.mojang.blaze3d.vertex.PoseStack;import com.mojang.math.Axis;import net.minecraft.client.Minecraft;import net.minecraft.client.renderer.*;import net.minecraft.world.item.*;
/** Source provider wins over older ItemRenderLibrary for derrick; pumpjack keeps its actual library matrices. */
public final class OilDrillItemRenderer extends BlockEntityWithoutLevelRenderer {
 public OilDrillItemRenderer(){super(Minecraft.getInstance().getBlockEntityRenderDispatcher(),Minecraft.getInstance().getEntityModels());}
 @Override public void renderByItem(ItemStack stack,ItemDisplayContext context,PoseStack poses,MultiBufferSource buffers,int light,int overlay){var kind=((OilDrillBlock)((BlockItem)stack.getItem()).getBlock()).kind;poses.pushPose();if(LegacyItemTransforms.isHeld(context))LegacyItemTransforms.held(poses,context);else poses.translate(.5,.5,.5);if(context==ItemDisplayContext.GUI){poses.scale(1F/16,-1F/16,1F/16);poses.translate(0,2,0);poses.mulPose(Axis.XP.rotationDegrees(-30));poses.mulPose(Axis.YP.rotationDegrees(45));poses.scale(-1,-1,-1);if(kind==OilDrillKind.WELL){poses.translate(0,-4,0);poses.scale(3,3,3);}else{poses.translate(0,-2,0);poses.mulPose(Axis.YP.rotationDegrees(90));poses.scale(4,4,4);}}else{boolean entity=context==ItemDisplayContext.GROUND||context==ItemDisplayContext.FIXED||context==ItemDisplayContext.NONE;if(entity)poses.scale(1.5F,1.5F,1.5F);else poses.translate(.5,.25,0);poses.scale(.25F,.25F,.25F);if(context!=ItemDisplayContext.THIRD_PERSON_LEFT_HAND&&context!=ItemDisplayContext.THIRD_PERSON_RIGHT_HAND)poses.mulPose(Axis.YP.rotationDegrees(90));}if(kind==OilDrillKind.WELL)poses.mulPose(Axis.YP.rotationDegrees(90));poses.scale(.5F,.5F,.5F);if(kind==OilDrillKind.PUMPJACK)poses.translate(0,0,3);OilDrillRenderer.all(kind,poses,buffers,light,overlay);poses.popPose();}
}
